bookInfoRule.name:
@js:r=org.jsoup.Jsoup.parse(result);
r.select("script,noscript,style,head>:not(meta),footer,[class~=^foot],[id~=^foot],a:has(>:last-child:matchesOwn(^分类$)),[value]").remove();

n=String(book.name);
m=String(r).replace(/(?:&nbsp;)+/g," ");
书=java.get("源");

if(x=(y=r.select('[property$=book_name]')).size()){
y=y.attr("content");
u=书.indexOf(y)
}else for(u=true,c=r.select("h1,h2,h3,strong").eachText();x<c.size();x++)if(
(y=c.get(x))!=''&&(u=书.indexOf(y),~u&&u<4))break;
if(!~(y=String(y)).indexOf(n)&&~u)n=y;

if((x=r.select("[property$=author]")
).size()){
x=String(x.attr("content")).replace(/^作\s*[者家][\s:：]*|(?!^)[/／｜|，,\s][^⚙️]*$/,"")
}else{
x=m.match(/>\s*([^>]+?)(?:\s*<\/[a-z]+>\s*|\s+)著\s*<|[\s\[\];?!,.()、，；？！。…─（）［］〖〗【】>《》](?:小说|漫画)?作\s*者(?![^>]+->)(?:[:：\s〖【（《［\[\(]|<[^it\/][^>]*>|<\/[^>]+>)+([^\s<">,，/／｜|\)\]］》）】〗]+)/);
x=x?x[1]?x[1]:x[2]:(x=r.select("#author,.author"),x.size()?String(x.first().text()).replace(/(?!^)[/／｜|，,\s][^⚙️]*$/,""):"")}

if(n.indexOf(x)>0&&!~java.get("key").indexOf(n))n=n.split(x)[0];
java.put("x",x);

y=r.select("meta[property~=(category|status)$]");
c=y.size()?String(y.eachAttr("content"))
.slice(1,-1).replace(/(?!^)\s*[，,./／｜|]\s*/,","):(y=m.match(/(?:[\s\[\];?!,.()、，；？！。…─（）［］〖〗【】》]|<[^a/][^>]*>|<\/[^>]+>)(?:[分大]\s*类|类\s*[型别])(?:[:：\s]|<[^>]+>)+([^\s<."/／｜|>]+)/))&&y[1];
if(c)java.put("v",c);

y=r.select("meta[property~=latest_chapter_name$]");

c=y.size()?y.attr("content"):(y=m.match(/>(?:\s*[更最]\s*[新近])+(?:\s*章\s*节)?(?:[:：\s\[]|<[^>]+>)+(?!\s*(?:-|&gt;)\s*<|[:：\s0-9T年月日时分秒*-]{5,}<|[^:：]+[^章\s]\s*[:：]\s*<|更新(?:时间)?[:：])([^<"/／｜|\]>]+)/))&&y[1];
if(c)java.put("z",c);

正=true;
if((key=String(java.get("custom"))).length){
if(~key.indexOf("全"))java.put("全",1);
if((
u=key.match(/[^\[\]]+(?=\])/),
c=~key.indexOf("录"),
y=~key.indexOf("单"),
baseUrl=u?u[0]:baseUrl,
(c||u)&&(baseUrl=c||y?(baseUrl=String((c=baseUrl.match(/(.+[^\d])(\d+)([^\d]*)$/))[1]+1+c[3]),
c=c[2]+'🌕'+c[1]+'🌕'+2+'🌕'+c[3],
baseUrl):baseUrl)
)||~key.indexOf("直")
)java.put("目",1),正=1;
if(~key.indexOf("录"))java.put("录",c),正=1;
if(y||~key.indexOf("#")){
if(!u){
if((网=key.match(/(\d+)#([^#]+)/))
&&(尾=网[1],网=网[2].match(/^(.*[^\d])([12])([^/?\d]*)$/))
||(尾=r.select('a[href~=\\d[^/?\\d]*$]:matches(^(尾|末|最后一)[頁页篇章回节節话話]$)')).size()
&&(网=r.select('a:matches(^2$)')).size()
&&(网=String(网.first().attr('href')).match(/^(.*[^\d])([12])([^/?\d]*)$/))
&&(尾=String(尾.first().attr('href')).match(/\d+(?=[^/?\d]*$)/)[0])){
c=尾+'🌕'+网[1]+'🌕'+网[2]+'🌕'+网[3]
}else if((c=r.select('a:matches(^(\\d+|…+|\\.+)$)')).size()){
if((网=String(c).split(/<a[^>]+>[^\d<]+<\/a>/)).length==2){
for(c=网[0],尾=网[1],x=+网[1].match(/>([^<]+)/)[1],网=网[0].match(/href="([^"]*[^\d])(\d+)([^/?\d"]*)"[^>]*>([^<]+)<[^<]+$/),j=+网[4],i=+网[2]-j;j<x;j++)c+="<a href='"+网[1]+(j+i)+网[3]+"'>"+j+"</a>";
c+=尾}
}else c=1}
java.put("单",c),正=false}
if(~key.indexOf("跳"))java.put("跳",1);
if(~key.indexOf("逆"))book.setReverseToc(true);
else book.setReverseToc(false);
if((u=~key.indexOf("图"))||~key.indexOf("原"))java.put("原",1);
if(~key.indexOf("动"))java.put("动",',{"webView":true}');
else if(~key.indexOf("静"))java.put("静",1);
if(u||~key.indexOf("字"))java.put("文",u?1:2)
}else book.setReverseToc(false);

y=r.select("meta[property$=description][content~=\\S]");
c=y.size()?y.get(y.size()-1).attr("content"):(r.select(':matchesOwn([\\u4e00-\\u9fa5]{2,})>:not(br),:not(body,br,:matchesOwn([\\s\\S]{50}),:has(body,:matchesOwn([\\s\\S]{50})))').remove(),r.select(":matchesOwn(\\S)").text());

java.put("g",String(c!=""?c:book.intro).replace(/[\snbsp;]*(?:&nbsp;|\s){2,}|\s*([？！。]+[”」』\]\}\)）｝】〗〕〉]?)\s*/g,"$1　　").replace(/(?=　　)/g,"\n"));

if(正==1)m=java.ajax(baseUrl);
