// 清理和分割结果
var lines = result.split(/[\r\n]+/);
var html = '';
for (var i = 0; i < lines.length; i++) {
    var url = lines[i]
        .trim()  // 去除首尾空格
        .replace(/^[^a-zA-Z]*/, '')  // 去除行首的非字母字符（如└、空格等）
        .replace(/[^a-zA-Z0-9:/._\-]+$/, '');  // 去除行尾的特殊字符

    // 只处理看起来像URL的行
    if (url.startsWith('http') && (url.includes('.jpg') || url.includes('.png') || url.includes('.jpeg'))) {
        html += '<img src="' + url + '">\n';  // 每个标签单独一行
    }
}

